    createContact: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    first_name?: string;
                    last_name?: string;
                    /**
                     * Format: email
                     * @description Normalized to lowercase. If the submitted identifiers resolve cleanly to one existing contact in this brand, that contact is updated (200) instead of duplicated. If email and phone identify different contacts in this brand, the request is rejected (422). Creates/updates the email channel with opt_in.
                     */
                    email?: string;
                    /** @description E.164 format. Creates/updates phone channel with opt_in */
                    phone?: string;
                    source?: string;
                    country_code?: string;
                    list_ids?: number[];
                    /**
                     * @description Custom key-value data. The reserved key `tags` holds an
                     *     array of string labels used for segmentation, e.g.
                     *     `{"tags": ["vip", "newsletter"]}`.
                     *
                     *     **Merge-on-resolve behavior (create path only):** when the
                     *     submitted email or phone resolves cleanly to an existing
                     *     contact, `data` is merged into the contact's existing data
                     *     rather than replaced. Blank incoming values are ignored;
                     *     caller-supplied non-reserved keys overwrite their
                     *     counterparts; the reserved enrichment keys `apollo`, `pdl`,
                     *     `attio`, `hubspot`, `stripe`, `shopify`, and `nitro` are
                     *     preserved from the stored contact;
                     *     and `tags` from both sides are unioned. The update endpoint
                     *     (`PATCH /v1/my/contacts/{id}`) replaces `data` wholesale
                     *     instead.
                     * @example {
                     *       "tags": [
                     *         "vip",
                     *         "newsletter"
                     *       ],
                     *       "plan": "pro"
                     *     }
                     */
                    data?: {
                        [key: string]: unknown;
                    };
                    channels_attributes?: {
                        /** @enum {string} */
                        kind?: "email" | "phone";
                        value?: string;
                        subscribed?: boolean;
                    }[];
                };
            };
        };
        responses: {
            /**
             * @description Existing contact updated in place. Returned when the submitted email
             *     and/or phone resolves cleanly to one existing contact in this brand.
             */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Contact"];
                };
            };
            /** @description Contact created */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Contact"];
                };
            };
            422: components["responses"]["ValidationError"];
        };
    };
