    createMessage: {
        parameters: {
            query?: never;
            header?: {
                /** @description Strongly recommended; mandatory from 2026-09-01 unless idempotency_key is supplied in the body. Prevents duplicate sends on retry. The same key with the same payload returns the original message; the same key with a different payload returns 409. Before the cutoff, keyless requests succeed with Deprecation and Sunset response headers. */
                "Idempotency-Key"?: string;
            };
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** @enum {string} */
                    channel: "email" | "sms";
                    /** @description Recipient email address or E.164 phone number */
                    to: string;
                    /** @description Email subject line (required for email channel) */
                    subject?: string;
                    /** @description Message body. Required for SMS. For email this is plain text (HTML in this field is escaped) and serves as the plain-text alternative when `html` is set. To send HTML, use `html` or `template_id`. */
                    body?: string;
                    /** @description Pre-rendered HTML body for email, used verbatim as the HTML part (not escaped). Use this to send your own fully-rendered HTML. Mutually exclusive with `template_id` (email only). */
                    html?: string;
                    /** @description Load email design from an existing template (email only) */
                    template_id?: number;
                    /** @description Optional contact to personalize with when rendering a template */
                    contact_id?: number;
                    /** @description Verified sender email for this email message. May include a display name, for example "Acme <hello@example.com>". */
                    from?: string;
                    /** @description Verified sender email for this email message. Alias of `from`. */
                    from_email?: string;
                    /** @description Sender display name for this email message */
                    from_name?: string;
                    /** @description Reply-to email address for this email message */
                    reply_to?: string;
                    /** @description Provider headers for this email message. Structural and Nitrosend-reserved headers are rejected. */
                    headers?: {
                        [key: string]: string;
                    };
                    /** @description Provider tags for this email message. Nitrosend-reserved tag keys are rejected and system tags are always controlled by Nitrosend. */
                    tags?: {
                        [key: string]: string;
                    };
                    /** @description Merge variables */
                    data?: {
                        [key: string]: unknown;
                    };
                    /** @description Stable idempotency key (alternative to header). Strongly recommended; mandatory from 2026-09-01. */
                    idempotency_key?: string;
                };
            };
        };
        responses: {
            /** @description Existing message returned for idempotency replay */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Message"];
                };
            };
            /** @description Message created */
            201: {
                headers: {
                    /** @description Present only on accepted keyless requests before the cutoff (RFC 9745). Value is the deprecation date, e.g. "@1785196800". */
                    Deprecation?: string;
                    /** @description Present only on accepted keyless requests before the cutoff (RFC 8594). Keyless sends are rejected from this date: "Tue, 01 Sep 2026 00:00:00 GMT". */
                    Sunset?: string;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Message"];
                };
            };
            /** @description Missing required idempotency key (enforced from 2026-09-01). Before the cutoff, keyless requests are accepted with Deprecation and Sunset headers. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Idempotency conflict or explicit sender selection required; no new message is retained in either case */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @example 409 */
                        code?: number;
                        message?: string;
                        /** @example true */
                        error?: boolean;
                        /** @enum {string} */
                        error_code?: "idempotency_conflict";
                    } | {
                        /** @enum {string} */
                        code: "sender_identity_selection_required";
                        message: string;
                        /** @constant */
                        error: true;
                        /** @enum {string} */
                        error_code: "sender_identity_selection_required";
                        retryable: boolean;
                        brand_subdomain: components["schemas"]["BrandSubdomain"];
                    };
                };
            };
            422: components["responses"]["ValidationError"];
            /** @description Admission evidence or the shared hosted-sender root is temporarily unavailable */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": (components["schemas"]["Error"] & {
                        /** @enum {string} */
                        error_code: "delivery_evidence_pending";
                        /** @constant */
                        retryable: true;
                        /** Format: date-time */
                        retry_at: string;
                    }) | {
                        /** @enum {string} */
                        code: "hosted_sender_root_unavailable";
                        message: string;
                        /** @constant */
                        error: true;
                        /** @enum {string} */
                        error_code: "hosted_sender_root_unavailable";
                        /** @constant */
                        retryable: true;
                        brand_subdomain: components["schemas"]["BrandSubdomain"];
                    };
                };
            };
        };
    };
